"""README.md is generated by scripts/make_readme.py from app/data.json and docs/backtests/*.csv."""
import json
import subprocess
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import make_readme  # noqa: E402

DATA = json.loads((ROOT / "app" / "data.json").read_text())
README = (ROOT / "README.md").read_text() if (ROOT / "README.md").exists() else ""


def test_readme_is_exactly_what_the_generator_writes():
    # every number in the README comes from the data; a hand edit or stale number fails here
    assert README == make_readme.render()


def test_readme_numbers_come_from_data_json():
    bt = DATA["meta"]["backtest"]
    assert f'{bt["station_day_wape"] * 100:.1f}%' in README
    assert f'{bt["station_day_mape"] * 100:.1f}%' in README
    assert f'{DATA["meta"]["rule_agreement"]:.0%}' in README
    assert f'{bt["complete_days_wape"] * 100:.1f}%' in README
    assert all(g["name"] in README for g in DATA["groups"] if not g["name"].startswith("Event"))
    assert "What we can't measure" in README and "summer scenario" in README.lower()
    assert "August 2024" in README and "19 complete days" in README


def test_headline_error_is_the_same_string_as_the_panel():
    sys.path.insert(0, str(ROOT / "app"))
    import view
    assert f"misses by **{view.error_label(DATA)}**" in README


def test_readme_recommendation_table_matches_csv():
    rec = pd.read_csv(ROOT / "data" / "recommendations.csv")
    for line in rec.line.unique():
        n = int(rec[rec.line == line].robust.sum())
        assert f"| {line} |" in README and f"| {n} of 18 |" in README


def test_required_sections_links_and_placeholders():
    for s in ("## What we found", "## How it works", "## Backtests: before and after the review",
              "## Groups do not improve the forecast", "## What we can't measure", "## Run it yourself",
              "docs/backtests/", "Live app: [https://appapppy-frrvdz2txlxxaxbbtxorew.streamlit.app](https://appapppy-frrvdz2txlxxaxbbtxorew.streamlit.app)", "docs/panel1.png", "docs/panel2.png", "docs/panel3.png",
              "202512", "M9 Olimpiyat Doğu", "not occupancy",
              "has not been checked", "Kurban Bayramı", "chosen on the 2024 special-day backtest",
              "separate window", "whole analysis period", "**Scaling.**"):
        assert s in README, s


def test_backtest_table_shows_old_and_new_values_side_by_side():
    old = pd.read_csv(ROOT / "docs" / "backtests" / "before-review.csv")
    new = pd.read_csv(ROOT / "docs" / "backtests" / "closed-0.2.csv")
    for df in (old, new):
        row = df[(df.test == "main Apr-May 2024") & (df.level == "station") & (df.measure == "station_day")].iloc[0]
        assert f"{row.wape * 100:.1f}%" in README
    assert "Before the review" in README and "Now (used in the panel)" in README


def test_check_mode_passes_on_committed_readme():
    r = subprocess.run([sys.executable, str(ROOT / "scripts" / "make_readme.py"), "--check"])
    assert r.returncode == 0
